; Touch effects: room 16 bonus, actor removal, deadly and trap tiles, exit edges
; $2fd6-$312b

; Room 16 bonus tile ($2D/$2E), Bruce only and at actor_y $A0 or more: one extra fall. It decrements the
; bonus count extra_fall_pickups_left of current_player (5 at the game start), adds 1 to falls_left, shows it,
; starts sound $8E and removes the bonus from the screen (draw_room16_bonus_taken).
collect_room16_bonus
; not executed $2fd6-$3000
        txa
        beq collect_room16_bonus_check_y
collect_room16_bonus_exit
        rts
collect_room16_bonus_check_y
        lda actor_y
        cmp #$a0
        bcc collect_room16_bonus_exit
        ldx current_player              ; current player
        dec extra_fall_pickups_left,x
        inc falls_left                  ; one more fall
        jsr show_falls_count            ; show the falls
        ldy #$8e
        jsr play_sound
; Draws tile $56 at column $24 of the text lines $0A and $0B over the room 16 bonus. Also called by
; room16_init when the bonus count of the player is 0.
draw_room16_bonus_taken
        lda #$56
        ldx #$0a
        ldy #$24
        jsr print_message
        lda #$56
        ldx #$0b
        ldy #$24
        jmp print_message
; Removes actor X from the room: clears its active bit, switches off its sprites, frees the extra sprites of
; actor_collision_code_a,X/_b,X (sprite_owner = $FF), clears its sprite images in both buffers
; (clear_yamo_sprite_data, clear_ninja_sprite_data) and restarts its spawn timer (reset_spawn_timer).
remove_actor
        lda #$01
        eor #$ff                        ; clear bit 0 (active)
        and actor_flags,x
        sta actor_flags,x
        ldy actor_main_sprite,x
        lda SPENA
        and sprite_clear_bit,y
        sta SPENA
        ldy actor_overlay_sprite,x
        bmi remove_actor_free_extra_a
        lda SPENA
        and sprite_clear_bit,y
        sta SPENA
remove_actor_free_extra_a
        lda actor_collision_code_a,x
        beq remove_actor_free_extra_b
        jsr set_sprite_slot_owner
        lda #$ff
        sta sprite_owner,y              ; sprite owner: none
remove_actor_free_extra_b
        lda actor_collision_code_b,x
        beq remove_actor_clear_images
        jsr set_sprite_slot_owner
        lda #$ff
        sta sprite_owner,y
remove_actor_clear_images
        cpx #$01
        bne remove_actor_clear_ninja
        jsr clear_yamo_sprite_data
        jmp remove_actor_restart_timer
remove_actor_clear_ninja
        jsr clear_ninja_sprite_data
remove_actor_restart_timer
        jmp reset_spawn_timer
; Deadly tile touched (not in room 18): sound effect $8C; an enemy is removed, Bruce dies
; (set_actor_hazard_death sets state $19).
touch_deadly_tile
        lda room
        cmp #$12
        bne touch_deadly_tile_kill
        rts
touch_deadly_tile_kill
        pha
        txa
        pha
        tya
        pha
        ldy #$8c
        jsr play_sound
        pla
        tay
        pla
        tax
        pla
        ldx current_actor
        beq touch_deadly_tile_bruce
        jmp remove_actor
touch_deadly_tile_bruce
        jmp set_actor_hazard_death
; Trap tile $60 touched: when its colour RAM is not yet 5, take a free one of the 3 burst trap slots
; (burst_trap_timer+n = 1), store the tile row - 1 (burst_trap_row+n) and column - 1 (burst_trap_col+n) and set
; the colour to $FD (5, marked). update_burst_traps animates the slots. When all slots are busy nothing happens.
touch_trap_tile
        lda row_ptr_top+1
        clc
        adc #>($d800 - game_screen)     ; row_ptr_top + $4C00: colour RAM of the tile
        sta row_ptr_top+1
        lda (row_ptr_top),y
        and #$07
        cmp #$05                        ; colour 5: already triggered
        beq touch_trap_tile_done
        lda burst_trap_timer
        bne touch_trap_tile_slot1
        lda #$01
        sta burst_trap_timer
        lda actor_cell_row,x
        sta burst_trap_row
        sty burst_trap_col
        dec burst_trap_col
        dec burst_trap_row
        jmp touch_trap_tile_mark
touch_trap_tile_slot1
        lda burst_trap_timer+1
        bne touch_trap_tile_slot2
        lda #$01
        sta burst_trap_timer+1
        lda actor_cell_row,x
        sta burst_trap_row+1
        sty burst_trap_col+1
        dec burst_trap_col+1
        dec burst_trap_row+1
        jmp touch_trap_tile_mark
touch_trap_tile_slot2
        lda burst_trap_timer+2
        bne touch_trap_tile_done
        lda #$01
        sta burst_trap_timer+2
        lda actor_cell_row,x
        sta burst_trap_row+2
        sty burst_trap_col+2
        dec burst_trap_col+2
        dec burst_trap_row+2
touch_trap_tile_mark
        lda #$fd
        sta (row_ptr_top),y
touch_trap_tile_done
        lda row_ptr_top+1
        sec
        sbc #>($d800 - game_screen)     ; back to the screen address
        sta row_ptr_top+1
        rts
; Exit permission of actor X. Returns carry clear when the actor may leave: always in room 11; at the left
; edge (actor_x < $10) after moving left (actor_move_queue+6,X); at the right edge (actor_x > $A1) after moving
; right (actor_move_queue+9,X); below actor_y $C5 while falling (state $0E); at the top (actor_y < $31) after
; moving up (actor_move_queue,X). Else carry set.
check_exit_edge
        lda room
        cmp #$0b
        beq check_exit_allowed
        sec
        lda actor_x,x
        cmp #$10
        bcs check_exit_right_edge
        lda actor_move_queue+6,x
        bne check_exit_allowed
check_exit_right_edge
        lda #$a1
        cmp actor_x,x
        bcs check_exit_bottom_edge
        lda actor_move_queue+9,x
        bne check_exit_allowed
check_exit_bottom_edge
        lda #$c5
        cmp actor_y,x
        bcs check_exit_top_edge
; not executed $30f7-$30fc
        lda actor_state,x
        cmp #$0e
        beq check_exit_allowed
check_exit_top_edge
        lda actor_y,x
        cmp #$31
        bcs check_exit_blocked
; not executed $3103-$3107
        lda actor_move_queue,x
        bne check_exit_allowed
check_exit_blocked
        sec
        rts
check_exit_allowed
        clc
        rts
; Moving character $62 touched on a ladder or vine (actor_contact,X bit 2): state $17 (ride) with timer $10,
; actor_step_delay,X = 0 and actor_ride_hold,X = 0 (not for a dying actor). Then the character is checked
; again from handle_tile_try_bonus.
touch_climb_tile
        lda actor_state,x
        cmp #$19
        beq touch_climb_tile_continue
        lda actor_contact,x
        and #$04
        beq touch_climb_tile_continue
        lda #$17
        sta actor_state,x
        lda #$10
        sta actor_timer,x
        lda #$00
        sta actor_step_delay,x
        sta actor_ride_hold,x
touch_climb_tile_continue
        lda (row_ptr_top),y
        jmp handle_tile_try_bonus
